struct Voice{int k,n,a=0;double ph=0;};double smp(Voice&v,double sr){double t=v.a/sr,o=0;if(v.k<4){if(v.k==0){double f=48+110*exp(-t*35);v.ph+=2*PI*f/sr;o=sin(v.ph)*exp(-t*16)+.12*sin(2*PI*900*t)*exp(-t*90);}else if(v.k==1){o=.55*noise(v.a*747796405u+17)*exp(-t*18);v.ph+=2*PI*180/sr;o+=.28*sin(v.ph)*exp(-t*22);}else if(v.k==2)o=.55*noise(v.a*2891336453u+91)*exp(-t*30);else o=.32*noise(v.a*277803737u+41)*exp(-t*55);}else{v.ph+=hz(v.n)/sr;if(v.ph>=1)v.ph-=1;double saw=2*v.ph-1,sine=sin(2*PI*v.ph),a=std::min(1.0,t/.008),dec=exp(-t*(v.k==4?3.2:2.0));o=(v.k==4?(saw*.65+sine*.35):(sine*.72+saw*.28))*a*dec;}v.a++;return o;}bool alive(const Voice&v,double sr){double q[]={.30,.22,.16,.10,.42,.62};return v.a<q[v.k]*sr;}
