void toggle(){if(playing){playing=false;if(ath.joinable())ath.join();}else{playing=true;ath=std::thread(audio);}InvalidateRect(win,nullptr,FALSE);}std::wstring dialog(bool save,const wchar_t*filter,const wchar_t*ext){wchar_t p[MAX_PATH]=L"";OPENFILENAMEW o{};o.lStructSize=sizeof(o);o.hwndOwner=win;o.lpstrFile=p;o.nMaxFile=MAX_PATH;o.lpstrFilter=filter;o.lpstrDefExt=ext;o.Flags=OFN_PATHMUSTEXIST|(save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);return(save?GetSaveFileNameW(&o):GetOpenFileNameW(&o))?p:L"";}
