void wav(){auto p=dialog(true,L"WAV Audio\0*.wav\0",L"wav");if(p.empty())return;constexpr int sr=44100;int sn=(int)(sr*60.0/bpm.load()/4.0),total=sn*STEPS;std::vector<int16_t>a(total*2);std::vector<Voice>v;for(int i=0;i<total;i++){if(i%sn==0){int s=i/sn;for(int t=0;t<D;t++)if(drums[t][s])v.push_back({t,0});for(int r=0;r<NOTES;r++){if(bass[r][s])v.push_back({4,47-r});if(melody[r][s])v.push_back({5,71-r});}}double x=0;for(auto&q:v)x+=smp(q,sr);v.erase(std::remove_if(v.begin(),v.end(),[&](const Voice&q){return!alive(q,sr);}),v.end());int16_t z=(int16_t)(std::clamp(x*.24*(master.load()/100.0),-1.0,1.0)*32767);a[i*2]=a[i*2+1]=z;}std::ofstream o(p,std::ios::binary);uint32_t ds=(uint32_t)a.size()*2,rs=36+ds,fs=16,rate=sr,br=sr*4;uint16_t pcm=1,ch=2,align=4,bits=16;o.write("RIFF",4);o.write((char*)&rs,4);o.write("WAVEfmt ",8);o.write((char*)&fs,4);o.write((char*)&pcm,2);o.write((char*)&ch,2);o.write((char*)&rate,4);o.write((char*)&br,4);o.write((char*)&align,2);o.write((char*)&bits,2);o.write("data",4);o.write((char*)&ds,4);o.write((char*)a.data(),ds);}
void layout(HWND h){RECT c;GetClientRect(h,&c);int w=c.right,H=c.bottom;newR={170,23,235,58};openR={240,23,305,58};saveR={310,23,395,58};exportR={400,23,485,58};playR={w/2-50,20,w/2+35,60};minusR={w/2+105,20,w/2+140,60};plusR={w/2+215,20,w/2+250,60};volR={w-300,34,w-170,46};int left=150,right=w-35,top=175,bottom=H-135,gap=4,dw=(right-left-gap*15)/16,dh=(bottom-top-18)/4;for(int r=0;r<D;r++)for(int s=0;s<STEPS;s++)dp[r][s]={left+s*(dw+gap),top+r*dh,left+s*(dw+gap)+dw,top+(r+1)*dh-8};int nw=(right-left)/STEPS,nh=(bottom-top)/NOTES;for(int r=0;r<NOTES;r++)for(int s=0;s<STEPS;s++)np[r][s]={left+s*nw,top+r*nh,left+(s+1)*nw-1,top+(r+1)*nh-1};int y=H-105;tabs[0]={210,y,285,y+36};tabs[1]={292,y,352,y+36};tabs[2]={359,y,450,y+36};tabs[3]={457,y,575,y+36};}
